/* Presentaciones */
#include "z.h"
#define MAXD 100
#define SW 180
typedef struct { char tit[100]; char *txt; long len; } sl_t;
static zwin *W, *P; static sl_t D[MAXD]; static int n, cur, theme, foc, tc, top, pi_; static te_t T; static char path[300], msg[100]; static int dirty;
static const u32 BG[4] = {0x0F172A, 0xFFFFFF, 0x134E4A, 0x7F1D1D}, FGT[4] = {0x5EEAD4, 0x0F766E, 0xFDE68A, 0xFDE68A}, FGB[4] = {0xE5E7EB, 0x1F2937, 0xECFDF5, 0xFEF2F2};
static void keep(void) { sl_t *s = &D[cur]; free(s->txt); s->txt = malloc(T.len + 1); memcpy(s->txt, T.t, T.len + 1); s->len = T.len; }
static void add(const char *t, const char *b, long l, int at) { if (n >= MAXD) return; memmove(&D[at + 1], &D[at], (n - at) * sizeof D[0]); sl_t *s = &D[at]; strncpy0(s->tit, t, 100); s->txt = malloc(l + 1); memcpy(s->txt, b, l); s->txt[l] = 0; s->len = l; n++; }
static void go(int i) { keep(); cur = i; te_set(&T, D[i].txt, D[i].len); T.cur = T.len; foc = 0; }
static void render(zwin *w, int x, int y, int W_, int H, sl_t *s, int mini) { int sc = mini ? 1 : W_ >= 900 ? 3 : 2, bs = mini ? 1 : W_ >= 900 ? 2 : 1; g_rect(w, x, y, W_, H, BG[theme]); zw_clip(w, x, y, W_, H); if (mini) { g_text(w, x + 6, y + 6, s->tit, FGT[theme]); g_rect(w, x + 6, y + 26, W_ - 12, 1, FGT[theme]); } else { int tw = g_textw(s->tit) * sc; g_text2(w, x + MAX(20, (W_ - tw) / 2), y + H / 10, s->tit, FGT[theme], sc); g_rect(w, x + W_ / 10, y + H / 10 + 16 * sc + 14, W_ * 8 / 10, 3, FGT[theme]); } int Y = y + (mini ? 32 : H / 10 + 16 * sc + 36), lh = 20 * bs, X = x + (mini ? 8 : W_ / 10), maxc = (W_ - (X - x) * 2) / (8 * bs) - 2; const char *p = s->txt; char ln[256]; while (*p && Y < y + H - lh) { const char *e = p; while (*e && *e != '\n') e++; const char *q = p; int first = 1; do { int c = 0; const char *r = q, *br = 0; while (r < e && c < maxc) { if (*r == ' ') br = r; r++; while (r < e && (*r & 0xC0) == 0x80) r++; c++; } if (r < e && br) r = br; int l = MIN(r - q, 250); memcpy(ln, q, l); ln[l] = 0; if (l || first) { if (first && l) { if (bs > 1) g_circle(w, X + 6, Y + 14, 5, FGT[theme], 1); else g_rect(w, X + 2, Y + 6, 4, 4, FGT[theme]); } if (bs > 1) g_text2(w, X + 24, Y, ln, FGB[theme], bs); else g_text(w, X + 12, Y, ln, FGB[theme]); Y += lh + (mini ? 0 : 4); } first = 0; q = r; while (q < e && *q == ' ') q++; } while (q < e && Y < y + H - lh); p = *e ? e + 1 : e; } zw_noclip(w); }
static void pbuild(zpdoc *d, const zpset *s, void *c) {
    double pw = zp_pw(d), ph = zp_ph(d), k = pw / 960.0; char *ln = malloc(4096);
    for (int i = 0; i < n; i++) { sl_t *x = &D[i]; zp_page(d); zp_rect(d, 0, 0, pw, ph, BG[theme], ZP_NONE, 0); zpflow f; zp_flow_init(&f, d, 60 * k); f.started = 1; f.y = 50 * k; zp_para(&f, ZPF_SANSB, 40 * k, FGT[theme], x->tit, 0, 24 * k);
        const char *p = x->txt; while (p && *p) { const char *e = strchr(p, '\n'); long l = MIN(e ? e - p : (long)strlen(p), 4000LL); memcpy(ln + 4, p, l); ln[l + 4] = 0; if (l) { memcpy(ln, "\xE2\x80\xA2 ", 4); zp_para(&f, ZPF_SANS, 24 * k, FGB[theme], ln, 0, 10 * k); } if (!e) break; p = e + 1; }
        char t[16]; snprintf(t, 16, "%d", i + 1); zp_text(d, pw - 50 * k, ph - 24 * k, ZPF_SANS, 12 * k, FGB[theme], t); }
    free(ln);
}
static void print_(void) { keep(); zp_default_land = 1; zp_dialog(path[0] ? strrchr(path, '/') + 1 : "Presentacion", pbuild, 0); }
static void draw(void) { keep(); g_clear(W, UI_BG); g_rect(W, 0, 0, W->w, 36, UI_PANEL); static const char *B[] = {"Nuevo", "Abrir", "Guardar", "+ Diapo", "Borrar", "Tema", "Presentar", "Imprimir"}; for (int i = 0; i < 8; i++) ui_button(W, 6 + i * 78, 5, 74, 26, B[i], i == 6 ? 2 : 0); g_text(W, 640, 10, msg, UI_MUTED); g_rect(W, 0, 36, SW, W->h - 36, UI_PANEL); int vis = (W->h - 44) / 108; for (int i = top; i < n && i < top + vis; i++) { int y = 42 + (i - top) * 108; render(W, 10, y, SW - 20, 98, &D[i], 1); g_frame(W, 9, y - 1, SW - 18, 100, i == cur ? UI_ACC : UI_LINE); char t[8]; snprintf(t, 8, "%d", i + 1); g_text(W, SW - 28, y + 78, t, FGB[theme]); } int X = SW + 14, wd = W->w - X - 14; g_text(W, X, 48, "Titulo", UI_MUTED); ui_input(W, X, 66, wd, 28, D[cur].tit, tc, foc == 1); g_text(W, X, 102, "Puntos (uno por linea)", UI_MUTED); g_rect(W, X, 120, wd, 150, UI_WHITE); g_frame(W, X, 120, wd, 150, foc == 0 ? UI_ACC : UI_LINE); T.cols = (wd - 12) / 8; zw_clip(W, X + 1, 121, wd - 2, 148); te_draw(W, &T, X + 6, 124, 142, 1, UI_TEXT, UI_ACC2, UI_ACC, 0); zw_noclip(W); int ph = W->h - 290, pw = MIN(wd, ph * 16 / 10); ph = pw * 10 / 16; render(W, X, 282, pw, ph, &D[cur], 0); g_frame(W, X, 282, pw, ph, UI_LINE); zw_present(W); }
static void draw_p(void) { render(P, 0, 0, P->w, P->h, &D[pi_], 0); char t[20]; snprintf(t, 20, "%d / %d", pi_ + 1, n); g_text(P, P->w - g_textw(t) - 14, P->h - 22, t, FGB[theme]); zw_present(P); }
static void save(int ask) { char p[300], dd[120]; z_docdir(dd); if (path[0]) strcpy(p, path); else snprintf(p, 300, "%s/presentacion.zdp", dd); if ((ask || !path[0]) && !ui_prompt("Guardar", "Archivo .zdp:", p, 290)) return; keep(); sb_t b = {0}; sb_f(&b, "ZDIAPOS1 %d\n", theme); for (int i = 0; i < n; i++) { sb_s(&b, "\x1e"); sb_s(&b, D[i].tit); sb_s(&b, "\n"); sb_add(&b, D[i].txt, D[i].len); } int e = z_writefile(p, b.p, b.n); free(b.p); snprintf(msg, 100, e ? "Error: %s" : _("Guardado%s"), e ? z_errstr(e) : ""); if (!e) { strcpy(path, p); dirty = 0; } char m[340]; snprintf(m, 340, "[prueba] diapos guardo: %s", e ? z_errstr(e) : "OK"); z_log(m); }
static void clear_(void) { for (int i = 0; i < n; i++) free(D[i].txt); n = 0; cur = 0; add("Titulo de la presentacion", "Primer punto\nSegundo punto", 26, 0); te_set(&T, D[0].txt, D[0].len); path[0] = 0; dirty = 0; }
static void open_(const char *p) { long l; char *d = z_readfile(p, &l); if (!d || strncmp(d, "ZDIAPOS1", 8)) { strcpy(msg, _("No se puede abrir")); free(d); return; } for (int i = 0; i < n; i++) free(D[i].txt); n = 0; theme = atoi(d + 9) & 3; char *q = strchr(d, 0x1e); while (q && *q == 0x1e) { q++; char *nl = strchr(q, '\n'); if (!nl) break; *nl = 0; char *t = nl + 1, *z = strchr(t, 0x1e); long len = z ? z - t : (long)strlen(t); add(q, t, len, n); q = z; } free(d); if (!n) { clear_(); return; } cur = 0; te_set(&T, D[0].txt, D[0].len); strncpy0(path, p, 300); dirty = 0; }
static int tdrag;
int main(const char *a) { int wp; a = z_print_arg(a, &wp); zsys s; z_sysinfo(&s); te_init(&T); W = zw_new("Presentaciones", -1, 0, MIN(900, (int)s.scr_w - 60), MIN(640, (int)s.scr_h - 100), WF_DECOR | WF_RESIZE); clear_(); if (a[0]) open_(a); draw(); if (wp) { print_(); draw(); } zevent e;
    for (;;) { if (!z_event(&e, -1)) continue; if (e.type == EV_REDRAW) { draw(); if (P) draw_p(); continue; } if (!P && e.type == EV_KEY && (e.ch == 14 || e.ch == 15 || e.ch == 16)) { e.type = EV_DOWN; e.btn = 1; e.mods = 0; e.y = 8; e.x = 6 + (e.ch == 15 ? 1 : e.ch == 16 ? 7 : 0) * 78 + 20; } if (P && e.win == (u32)P->id) { if (e.type == EV_KEY) { if (e.ch == 27) { zw_close(P); P = 0; draw(); continue; } if (e.key == K_RIGHT || e.key == K_DOWN || e.ch == ' ' || e.ch == '\n' || e.key == K_PGDN) pi_ = MIN(pi_ + 1, n - 1); else if (e.key == K_LEFT || e.key == K_UP || e.key == K_PGUP) pi_ = MAX(pi_ - 1, 0); draw_p(); } else if (e.type == EV_DOWN) { pi_ = e.btn & 2 ? MAX(pi_ - 1, 0) : MIN(pi_ + 1, n - 1); draw_p(); } continue; } if (e.win != (u32)W->id) continue; if (e.type == EV_CLOSE) { if (!dirty || ui_confirm("Salir", "Hay cambios sin guardar. Salir?")) return 0; continue; } if (e.type == EV_RESIZE) { zw_resized(W, e.x, e.y); draw(); continue; } if (e.type == EV_WHEEL) { if (e.x < SW) top = MAX(0, MIN(top - (int)e.key, n - 1)); draw(); continue; }
        if (e.type == EV_KEY) { if (e.ch == 19) save(0); else if (e.key == 0x3E) goto present; else if (foc == 1) { if (e.ch == '\n') foc = 0; else if (ui_input_key(D[cur].tit, 90, &tc, &e)) dirty = 1; } else if (te_key(&T, &e, 6) == 2) dirty = 1; draw(); continue; } if (e.type == EV_MOVE && tdrag) { if (!e.btn) tdrag = 0; else { te_click(&T, e.x - SW - 14 - 6, e.y - 124, 1, 1); draw(); } continue; } if (e.type == EV_UP) { tdrag = 0; continue; } if (e.type != EV_DOWN) continue; int X = SW + 14;
        if (e.y < 36 && (e.x - 6) / 78 == 7) { print_(); draw(); continue; } if (e.y < 36) { int b = (e.x - 6) / 78; if (b == 0) { if (!dirty || ui_confirm("Nuevo", "Descartar cambios?")) clear_(); } else if (b == 1) { char p[300], dd[120]; z_docdir(dd); snprintf(p, 300, "%s/presentacion.zdp", dd); if (ui_prompt("Abrir", "Archivo .zdp:", p, 290)) open_(p); } else if (b == 2) save(0); else if (b == 3) { keep(); add("Nueva diapositiva", "", 0, cur + 1); go(cur + 1); dirty = 1; } else if (b == 4 && n > 1) { free(D[cur].txt); D[cur].txt = 0; memmove(&D[cur], &D[cur + 1], (n - cur - 1) * sizeof D[0]); n--; if (cur >= n) cur = n - 1; te_set(&T, D[cur].txt, D[cur].len); dirty = 1; } else if (b == 5) { theme = (theme + 1) & 3; dirty = 1; } else if (b == 6) { present: keep(); pi_ = cur; P = zw_new("Presentacion", 0, 0, s.scr_w, s.scr_h, WF_POPUP); draw_p(); z_log("[prueba] diapos presentando"); continue; } } else if (e.x < SW) { int i = top + (e.y - 42) / 108; if (i < n && e.y >= 42) go(i); } else if (e.y >= 66 && e.y < 94) { foc = 1; if (!(e.btn & 2)) ui_input_click(W, &e, D[cur].tit, &tc); else tc = strlen(D[cur].tit); if ((e.btn & 2) && ui_input_menu(W, D[cur].tit, 90, &tc, &e)) dirty = 1; } else if (e.y >= 120 && e.y < 270) { foc = 0; if (e.btn & 2) { if (te_menu(W, &T, &e) == 2) dirty = 1; } else { te_click(&T, e.x - X - 6, e.y - 124, 1, e.mods & M_SHIFT); tdrag = 1; } } draw(); }
}
